const input = $input.first();
const json = (input && input.json) || {};

let issueKey = '';
let project = '';
let skill = '';
let testFiles = '';
let testCommand = '';

// Ưu tiên trích xuất từ body -> params -> query -> root json
const candidates = [json.body, json.params, json.query, json].filter(c => c && typeof c === 'object');

for (const c of candidates) {
  if (!issueKey && c.issueKey) issueKey = String(c.issueKey).trim();
  if (!project && c.project) project = String(c.project).trim();
  if (!skill && c.skill) skill = String(c.skill).trim();
  if (!testFiles && c.testFiles) testFiles = String(c.testFiles).trim();
  if (!testCommand && c.testCommand) testCommand = String(c.testCommand).trim();
}

// Fallback regex nếu issueKey nằm trong câu lệnh hoặc text
if (!issueKey) {
  const textSource = json.originalCommand || json.text || (json.body && json.body.text) || '';
  const match = String(textSource).match(/\b([A-Za-z0-9]+-[0-9]+)\b/);
  if (match) {
    issueKey = match[1];
  }
}

// 1. Nhận diện nguồn gọi
let triggerSource = json._triggerSource || (json.body && json.body._triggerSource) || 'webhook';
try {
  const trigWebhook = $('Webhook').first();
  if (trigWebhook && trigWebhook.json) {
    triggerSource = 'webhook';
  }
} catch (_) {}
try {
  const trigExec = $('Execute Workflow Trigger').first();
  if (trigExec && trigExec.json && Object.keys(trigExec.json).length > 0) {
    triggerSource = 'executeWorkflow';
  }
} catch (_) {}

if (!issueKey) {
  return [{
    json: {
      error: 'Thiếu tham số issueKey.',
      issueKey: '',
      project: project,
      skill: skill,
      testFiles: testFiles,
      testCommand: testCommand,
      _triggerSource: triggerSource
    }
  }];
}

return [{
  json: {
    issueKey: issueKey.toUpperCase(),
    project: (project || '').trim(),
    skill: (skill || 'run-test').trim(),
    testFiles: testFiles,
    testCommand: testCommand,
    _triggerSource: triggerSource
  }
}];

const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const input = $input.first();
const issueKey = (input.json.issueKey || '').toUpperCase();
let project = (input.json.project || '').trim();
const reqTestFiles = (input.json.testFiles || '').trim();

let procEnv = {};
let procCwd = '';
try {
  const proc = require('process');
  if (proc) {
    procEnv = proc.env || {};
    if (typeof proc.cwd === 'function') procCwd = proc.cwd();
  }
} catch (_) {}

if (input.json.error || !issueKey) {
  return [{ json: { stdout: '', stderr: input.json.error || 'Thiếu tham số issueKey.', exitCode: 1, error: { message: input.json.error || 'Thiếu tham số issueKey.' }, project, issueKey, cwd: procCwd } }];
}

let cwd = ($env && $env.AGENT_WORKSPACE_DIR) || procCwd || '';

let projects = {};
try {
  const projectsFile = [
    path.resolve(cwd, 'config', 'projects.json'),
    path.resolve(cwd, 'projects.json')
  ].find(p => fs.existsSync(p));
  if (projectsFile) {
    projects = JSON.parse(fs.readFileSync(projectsFile, 'utf8'));
  }
} catch (e) {}

if (project) {
  if (projects[project]) {
    cwd = projects[project];
  } else {
    const scanDirsRaw = (typeof $env !== 'undefined' && $env.PROJECT_SCAN_DIRS) || procEnv.PROJECT_SCAN_DIRS || '';
    const scanDirs = scanDirsRaw.split(',').map(s => s.trim().replace(/^["']|["']$/g, '')).filter(Boolean);
    let foundDir = '';
    for (const sDir of scanDirs) {
      const candidate = path.resolve(sDir, project);
      if (fs.existsSync(candidate)) { foundDir = candidate; break; }
    }
    if (foundDir) cwd = foundDir;
    else if (fs.existsSync(path.resolve(cwd, project))) cwd = path.resolve(cwd, project);
  }
} else {
  const projectKeys = Object.keys(projects);
  if (projectKeys.length === 1) {
    cwd = projects[projectKeys[0]];
    project = projectKeys[0];
  } else {
    const candidateDirs = [
      path.resolve(cwd, 'workspace', 'issues', issueKey, 'test'),
      path.resolve(cwd, 'workspace', issueKey, 'test')
    ];
    let currentTestDir = candidateDirs.find(d => fs.existsSync(d));
    if (!currentTestDir) {
      for (const [pName, pPath] of Object.entries(projects)) {
        const pCandidates = [
          path.resolve(pPath, 'workspace', 'issues', issueKey, 'test'),
          path.resolve(pPath, 'workspace', issueKey, 'test')
        ];
        const found = pCandidates.find(d => fs.existsSync(d));
        if (found) {
          cwd = pPath;
          project = pName;
          currentTestDir = found;
          break;
        }
      }
    }
  }
}

let ticketDir = path.resolve(cwd, 'workspace', 'issues', issueKey);
if (!fs.existsSync(ticketDir)) {
  ticketDir = path.resolve(cwd, 'workspace', issueKey);
}
const testDir = path.resolve(ticketDir, 'test');
const stepsDir = path.resolve(testDir, 'steps');
const resultDir = path.resolve(testDir, 'result');

if (!fs.existsSync(resultDir)) {
  fs.mkdirSync(resultDir, { recursive: true });
}

let target = '';
if (reqTestFiles) {
  target = path.resolve(cwd, reqTestFiles);
} else if (fs.existsSync(stepsDir)) {
  target = stepsDir;
} else if (fs.existsSync(testDir)) {
  target = testDir;
} else {
  return [{ json: { stdout: '', stderr: 'Không tìm thấy thư mục test', exitCode: 4, error: { message: 'Không tìm thấy thư mục test' }, project, issueKey, cwd } }];
}

const logFile = path.join(resultDir, 'test-output.log');
const junitFile = path.join(resultDir, 'junit.xml');

const logStream = fs.createWriteStream(logFile);

const args = [
  target,
  '-v',
  '--tb=short',
  '--timeout=60',
  '-o', 'python_files=test*.py *test.py test-*.py *-test.py test_*.py *_test.py',
  `--junitxml=${junitFile}`
];

return new Promise((resolve) => {
  const child = spawn('pytest', args, { cwd: cwd, shell: false });
  let stdoutData = '';
  let stderrData = '';

  child.stdout.on('data', (data) => {
    stdoutData += data.toString();
    logStream.write(data);
  });

  child.stderr.on('data', (data) => {
    stderrData += data.toString();
    logStream.write(data);
  });

  let isTimeout = false;
  const timer = setTimeout(() => {
    isTimeout = true;
    child.kill('SIGKILL');
  }, 600000);

  child.on('close', (code, signal) => {
    clearTimeout(timer);
    logStream.end();

    let exitCode = code;
    let message = '';

    if (isTimeout || signal === 'SIGKILL') {
      exitCode = 124;
      message = 'SUITE TIMEOUT: Chạy test quá 10 phút';
    }

    resolve([{
      json: {
        stdout: stdoutData,
        stderr: stderrData,
        exitCode: exitCode !== null ? exitCode : 1,
        message: message,
        project: project,
        issueKey: issueKey,
        cwd: cwd,
        logFile: logFile,
        junitFile: junitFile
      }
    }]);
  });

  child.on('error', (err) => {
    clearTimeout(timer);
    logStream.end();
    resolve([{
      json: {
        stdout: stdoutData,
        stderr: err.message,
        exitCode: 1,
        error: { message: err.message },
        project: project,
        issueKey: issueKey,
        cwd: cwd
      }
    }]);
  });
});

const fs = require('fs');
const path = require('path');

const input = $input.first();
const extractNode = (typeof $('Extract issueKey') !== 'undefined') ? $('Extract issueKey').first().json : {};
const issueKey = extractNode.issueKey || input.json.issueKey || '';
const project = extractNode.project || input.json.project || '';
const procCwd = (() => { try { return require('process').cwd(); } catch (_) { return ''; } })();
const cwd = input.json.cwd || ($env && $env.AGENT_WORKSPACE_DIR) || procCwd || '';
const targetLabel = project ? (project + ' / ' + issueKey) : issueKey;
const triggerSource = extractNode._triggerSource || input.json._triggerSource || 'webhook';

if (!issueKey || extractNode.error) {
  const errMsg = extractNode.error || 'Thiếu issueKey hợp lệ.';
  return [{ json: { success: false, verdict: 'ERROR', errorCode: 'MISSING_ISSUEKEY', message: errMsg, _triggerSource: triggerSource } }];
}

const execRes = input.json;
const exitCode = execRes.exitCode;
const isTimeout = exitCode === 124 || (execRes.message && execRes.message.includes('TIMEOUT'));

let verdict = 'PASS';
let errorCode = null;

if (isTimeout) {
  verdict = 'TIMEOUT';
  errorCode = 'SUITE_TIMEOUT';
} else if (exitCode === 0) {
  verdict = 'PASS';
} else if (exitCode === 1) {
  verdict = 'FAIL';
  errorCode = 'TEST_FAILED';
} else if (exitCode === 2) {
  verdict = 'ERROR';
  errorCode = 'USER_INTERRUPTION';
} else if (exitCode === 3) {
  verdict = 'ERROR';
  errorCode = 'INTERNAL_ERROR';
} else if (exitCode === 4) {
  verdict = 'ERROR';
  errorCode = 'USAGE_ERROR';
} else if (exitCode === 5) {
  verdict = 'ERROR';
  errorCode = 'NO_TESTS_COLLECTED';
} else {
  verdict = 'ERROR';
  errorCode = 'UNKNOWN_ERROR';
}

const success = (verdict === 'PASS');
let resultDir = path.resolve(cwd, 'workspace', 'issues', issueKey, 'test', 'result');
if (!fs.existsSync(path.resolve(cwd, 'workspace', 'issues', issueKey))) {
  resultDir = path.resolve(cwd, 'workspace', issueKey, 'test', 'result');
}
if (!fs.existsSync(resultDir)) {
  fs.mkdirSync(resultDir, { recursive: true });
}

const reportMd = [
  `# Báo Cáo Kiểm Thử Tự Động: ${issueKey}`,
  '',
  `| Thuộc tính | Giá trị |`,
  `| :--- | :--- |`,
  `| **Issue Key** | \`${issueKey}\` |`,
  `| **Project** | \`${project || 'default'}\` |`,
  `| **Verdict** | **${verdict}** |`,
  `| **Mã lỗi** | \`${errorCode || 'N/A'}\` |`,
  `| **Thời Gian** | \`${new Date().toISOString()}\` |`
].join('\n');

try {
  fs.writeFileSync(path.join(resultDir, 'report.md'), reportMd, 'utf8');
} catch (e) {
  throw new Error('REPORT_WRITE_FAILED: ' + e.message);
}

const runStatus = {
  issueKey, project, verdict, errorCode, exitCode, timestamp: new Date().toISOString()
};
try {
  fs.writeFileSync(path.join(resultDir, 'run-status.json'), JSON.stringify(runStatus, null, 2), 'utf8');
} catch (e) {
  throw new Error('REPORT_WRITE_FAILED: ' + e.message);
}

const statusIcon = success ? '✅' : (verdict === 'FAIL' ? '❌' : (verdict === 'TIMEOUT' ? '⏱️' : '⛔'));
const message = `🚀 **[QA Automation]** Kết quả chạy kiểm thử cho ticket **${targetLabel}**:\n` +
                `- Verdict: ${statusIcon} **${verdict}**\n` +
                (errorCode ? `- Lỗi: \`${errorCode}\`\n` : '');

return [{
  json: {
    success,
    verdict,
    errorCode,
    message,
    reportText: message,
    issueKey,
    project,
    exitCode,
    _triggerSource: triggerSource
  }
}];
